    private void jTextField1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jTextField1ActionPerformed
        String textoIngresado = jTextField1.getText().trim();
    
    //Variables para guardar la información que mostraremos
    String detalle = "";
    String instrucciones = "";
    
    //Evalua qué número eligió el usuario
    switch (textoIngresado) {
        case "1":
            detalle = "Ejercicio: Sentadilla\nGrupo Muscular: Pierna\nNivel: Principiante / Intermedio";
            instrucciones = "1. Separa los pies a la anchura de los hombros.\n2. Baja la cadera manteniendo la espalda recta.\n3. Desciende hasta que los muslos estén paralelos al suelo.\n4. Sube empujando desde los talones.";
            break;
            
        case "2":
            detalle = "Ejercicio: Press de Banca\nGrupo Muscular: Pecho\nNivel: Intermedio";
            instrucciones = "1. Acuéstate boca arriba en el banco plano.\n2. Toma la barra con las manos un poco más abiertas que los hombros.\n3. Baja la barra de forma controlada hasta el pecho.\n4. Empuja hacia arriba extendiendo los brazos.";
            break;
            
        case "3":
            detalle = "Ejercicio: Dominadas\nGrupo Muscular: Espalda\nNivel: Avanzado";
            instrucciones = "1. Agárrate de la barra con las palmas hacia adelante.\n2. Cuélgate con los brazos completamente extendidos.\n3. Sube elevando el pecho hacia la barra usando la espalda.\n4. Baja de forma lenta y controlada.";
            break;
            
        case "4":
            detalle = "Ejercicio: Curl de Bíceps\nGrupo Muscular: Brazo\nNivel: Principiante";
            instrucciones = "1. Párate derecho sosteniendo mancuernas a los lados.\n2. Mantén los codos pegados al torso.\n3. Flexiona los brazos elevando el peso hacia los hombros.\n4. Baja lentamente a la posición inicial.";
            break;
            
        case "5":
            detalle = "Ejercicio: Zancadas / Lunges\nGrupo Muscular: Pierna\nNivel: Principiante";
            instrucciones = "1. Da un paso largo hacia adelante con una pierna.\n2. Baja la cadera hasta que ambas rodillas formen ángulos de 90 grados.\n3. Impúlsate con el pie delantero para regresar al inicio.";
            break;
            
        case "6":
            detalle = "Ejercicio: Press Militar\nGrupo Muscular: Hombro\nNivel: Intermedio";
            instrucciones = "1. Sostén la barra a la altura de los hombros.\n2. Contrae el abdomen y empuja la barra verticalmente hacia arriba.\n3. Baja la barra de forma controlada hasta la barbilla o clavícula.";
            break;
            
        case "7":
            detalle = "Ejercicio: Extensiones de Tríceps\nGrupo Muscular: Brazo\nNivel: Principiante";
            instrucciones = "1. Sujeta una mancuerna o polea por encima de la cabeza.\n2. Mantén los codos fijos apuntando hacia arriba.\n3. Extiende los brazos hacia arriba y regresa lentamente.";
            break;
            
        case "8":
            detalle = "Ejercicio: Peso Muerto\nGrupo Muscular: Pierna / Espalda\nNivel: Avanzado";
            instrucciones = "1. Colócate frente a la barra con los pies separados a la anchura de caderas.\n2. Agáchate con la espalda recta y toma la barra.\n3. Eleva la carga estirando rodillas y cadera simultáneamente.";
            break;
            
        case "9":
            detalle = "Ejercicio: Remo con Barra\nGrupo Muscular: Espalda\nNivel: Intermedio";
            instrucciones = "1. Inclina el tronco hacia adelante manteniendo la espalda totalmente recta.\n2. Toma la barra con ambas manos.\n3. Lleva la barra hacia el abdomen contrayendo la espalda.";
            break;
            
        case "10":
            detalle = "Ejercicio: Aperturas con Mancuernas\nGrupo Muscular: Pecho\nNivel: Intermedio";
            instrucciones = "1. Acuéstate en el banco con mancuernas arriba de tu pecho.\n2. Abre los brazos con una ligera flexión en los codos de forma arqueada.\n3. Regresa al centro apretando el pecho.";
            break;
            
        default:
            detalle = "Ejercicio no encontrado.";
            instrucciones = "Por favor, ingrese un número válido del 1 al 10.";
            break;
    }
    
    //Muestra los textos en las áreas correspondientes
    jTextArea1.setText(detalle);
    jTextArea2.setText(instrucciones);

    }//GEN-LAST:event_jTextField1ActionPerformed

    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        // Pregunta si realmente desea salir de la sección
    int opcion = javax.swing.JOptionPane.showConfirmDialog(this, 
        "¿Estás seguro que deseas salir de esta sección?", 
        "Salir", 
        javax.swing.JOptionPane.YES_NO_OPTION);
        
    if (opcion == javax.swing.JOptionPane.YES_OPTION) {
        this.dispose(); //Cierra esta ventana y regresa al menú principal
    }

    }//GEN-LAST:event_jButton1ActionPerformed

    
